// Тикет #6a86f7eda7b2 (F-91) — עבר QA 11.10.2026. Шаг «утверждение записи админом в приложении → пользователь слышит её», проверен на iPhone 11.10 17:28–17:30:
// до утверждения у пользователя «אין הקראה לקטע הזה» и «השמע» неактивна; админ (аккаунт клиента) «אישור ההקראה ופרסומה» →
// «אושרה על ידי … — מוצעת להשמעה למשתמשים»; у пользователя «הקראה: X · אושרה על ידי Y», «השמע» активна.
// Опора: F-91 AC4 (אין הקראה — מסומן), F-92 AC4 (מי הקליט ומי אישר); решение 06.10 — админ = גורם מאשר.
// ПРЕДУСЛОВИЕ: на ערבית אשכנז קטע 3 «המעריב ערבים» есть запись «ממתינה לאישור». ОБНОВЛЕНО 13.10.2026: загрузка MP3 ЕСТЬ в приложении
// (F-92 #6a86f7ed9d38 עבר QA 13.10): админка приложения → «עריכת קטע» → «מי הקליט» = «בודק QA» → «העלאת קובץ MP3» → Files → arvit-ashk-k3.mp3
// (файл .qa/research/rec-pages/arvit-ashk-k3.mp3 заранее положить в «Файлы» на iPhone); web-админка /admin — запасной путь.
// Отличие от specs/admin/ad-07 / ad-10 (загрузка + утверждение + удаление): здесь только утверждение уже загруженной записи.
// Нет записи «ממתינה לאישור» — тест пропускается. Порядок списка: rc-05 → rc-02/03/04 → rc-06 (удаление записей).
// Аккаунт: клиент (ADMIN) — он же видит экран пользователя (11.10 проверяли так). Вход ADMIN без QA_ADMIN_* — ручной.
// ОБНОВЛЕНО 25.10.2026: полный жизненный цикл записи на СВОЁМ QA קטע («ברכת הלבנה · אשכנז», без правки чужого текста) — specs/qa-2510/q-17
//  (кейс AD-13); удаление קטע с записью — с 26.10 (#544d9c עבר QA) прямо вместе с записью, без «הסרת ההקראה» (q-18, кейс AD-14).
import { expect } from '@wdio/globals';
import { byText, byTextContains, byTextMatches, scrollToText } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
import { asAdmin, openAdminPrayer, openSection, openUserArvit3, REC_CARD, REC_PENDING, REC_APPROVE_BTN, REC_APPROVED_RE } from '../_lib/admin.ts';
import { playerButton, recordingLine, shown, skipWith } from '../_lib/app-0710.ts';

describe('Озвучка: утверждение записи в приложении', () => {
  afterEach(async () => { await toHome(); });

  it('RC-05 запись «ממתינה לאישור» не слышна пользователю → утверждение в админке приложения → «הקראה: … · אושרה על ידי …» #6a86f7eda7b2 @data', async function () {
    await asAdmin();

    // 1. Админка: у קטע 3 запись ждёт утверждения.
    await openAdminPrayer('ערבית', 'אשכנז');
    await openSection('המעריב ערבים');
    await scrollToText(REC_CARD);
    if (!(await shown(byTextContains(REC_PENDING)))) skipWith(this, 'нет записи «ממתינה לאישור» на ערבית אשכנז קטע 3 — загрузить в админке приложения («העלאת קובץ MP3»)');

    // 2. Экран пользователя до утверждения: записи нет (F-91 AC4).
    await toHome();
    await openUserArvit3();
    await scrollToText('האזן להקראה');
    await expect(byText('אין הקראה לקטע הזה')).toBeDisplayed();
    await expect(recordingLine()).not.toBeDisplayed();
    await expect(await playerButton('השמע')).toBeDisabled();

    // 3. Админка приложения: «אישור ההקראה ופרסומה» → «אושרה על ידי … — מוצעת להשמעה למשתמשים».
    await toHome();
    await openAdminPrayer('ערבית', 'אשכנז');
    await openSection('המעריב ערבים');
    await scrollToText(REC_APPROVE_BTN);
    await (await byText(REC_APPROVE_BTN)).click();
    await expect(await byTextMatches(REC_APPROVED_RE)).toBeDisplayed({ wait: 20000 });

    // 4. Экран пользователя: строка «הקראה: X · אושרה על ידי Y», «השמע» активна, без автозапуска (S-25 AC1).
    await toHome();
    await openUserArvit3();
    await scrollToText('האזן להקראה');
    await expect(recordingLine()).toHaveText(/הקראה: .+ · אושרה על ידי .+/);
    await expect(await playerButton('השמע')).toBeEnabled();
    await expect(byText('השהה')).not.toBeDisplayed();
  });
});
